import Mux from '@mux/mux-node';

const mux = new Mux({
  tokenId: process.env.MUX_TOKEN_ID!,
  tokenSecret: process.env.MUX_TOKEN_SECRET!,
});

// Create an asset by providing a video URL
const asset = await mux.video.assets.create({
  input: [{ url: 'https://example.com/video.mp4' }],
  playback_policy: ['public'],
  video_quality: 'basic',
});

console.log('Asset ID:', asset.id);
console.log('Status:', asset.status); // 'preparing' initially

// Playback ID for streaming (available once status is 'ready')
const playbackId = asset.playback_ids?.[0]?.id;
console.log('Playback URL:', `https://stream.mux.com/${playbackId}.m3u8`);

import MuxPlayer from '@mux/mux-player-react';

export function VideoPlayer({ playbackId }: { playbackId: string }) {
  return (
    <MuxPlayer
      playbackId={playbackId}
      metadata={{
        video_id: playbackId,
        video_title: 'My Video',
        viewer_user_id: 'user-123',
      }}
      accentColor="#7c3aed"
      autoPlay={false}
      style={{ width: '100%', aspectRatio: '16/9' }}
    />
  );
}
